import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, toJob, WORKER_STALE_MS, type JobRow } from './db.ts';
import { parseSubmission, type FieldError } from './validate.ts';

const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)
`);
const selectHeartbeat = db.prepare("SELECT ts FROM heartbeat WHERE name = 'worker'");

const asRow = (x: unknown) => x as JobRow | undefined;

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.') ;
  void allow;
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function health(res: ServerResponse): void {
  const hb = selectHeartbeat.get() as { ts: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.ts <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function listJobs(res: ServerResponse): void {
  const rows = selectAll.all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, id: string): void {
  const row = asRow(selectById.get(id));
  if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
  send(res, 200, toJob(row));
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const keyHeader = req.headers['idempotency-key'];
  const parsed = parseSubmission(req.headers['content-type'], raw, keyHeader === undefined ? undefined : String(keyHeader));
  if (!parsed.ok) return sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
  const sub = parsed.value;

  const now = new Date().toISOString();
  db.exec('BEGIN IMMEDIATE');
  try {
    if (sub.idempotencyKey !== undefined) {
      const existing = asRow(selectByKey.get(sub.idempotencyKey));
      if (existing) {
        db.exec('COMMIT');
        if (existing.input === sub.input && existing.steps === sub.steps && existing.fail_attempts === sub.failAttempts) {
          return send(res, 200, toJob(existing));
        }
        return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    insertJob.run(id, sub.input, sub.steps, sub.failAttempts, sub.idempotencyKey ?? null, Date.now(), now, now);
    const row = asRow(selectById.get(id))!;
    db.exec('COMMIT');
    return send(res, 201, toJob(row));
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

function page(res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

function decodeId(raw: string): string {
  try {
    return decodeURIComponent(raw);
  } catch {
    return raw;
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? '';

  if (pathname === '/health') return method === 'GET' ? health(res) : methodNotAllowed(res, 'GET');
  if (pathname === '/') return method === 'GET' ? page(res) : methodNotAllowed(res, 'GET');
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method === 'GET') return getJob(res, decodeId(match[1]!));
    return methodNotAllowed(res, 'GET');
  }
  return sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error(err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

